export const CreateObjectView = observer(({model}: {model: CreateObjectModel}) => {
  return (
    <div id="create-object-container"> 
      {/* Asset Selection and Creation */}
      <button id="select-asset-button" onClick={() => {
        if (value) {
          model.createObject(value).then(() => { // Add then callback for smoother UX indication
            model.setSelectedAsset(value);
          });
        }
      }}>Select Asset</button> 

      {/* Display Available Assets */}
      <ul id="available-assets-list">
        {model.availableAssets.map((asset, index) => (
          <li key={index} id={`asset-${index}`}> {/* Add unique IDs to list items */}
            {asset} 
          </li>
        ))}
      </ul>

      {/* Cleanup Button */}
      <button id="cleanup-scene-button" onClick={model.cleanupScene}>Cleanup scene</button>
    </div>
  )
});
```

