function swapAdjectives(sentence) {
  const words = sentence.split(' ');
  const adjectiveIndices = []; // Track positions of adjectives

  // 1. Identify Adjectives: (Verbosity - Explanation)
  for (let i = 0; i < words.length; i++) {
    if (isAdjective(words[i])) {  // Assume a simple adjective detection helper function exists (see below)
      adjectiveIndices.push(i);
    }
  }

  // 2. Swap if Found:
  if (adjectiveIndices.length >= 2) {  // Ensure at least two adjectives exist
    const [index1, index2] = adjectiveIndices.slice(0, 2);  // Get first two indices
    [words[index1], words[index2]] = [words[index2], words[index1]]; // Swap using destructuring
  }

  // 3. Reconstruct & Return:
  return words.join(' ');
}

// Helper Function (expandable for more robust adjective detection)
function isAdjective(word) {
  // Basic check -  enhance with NLP techniques for accuracy
  return ['beautiful', 'green', 'small', 'tall', ... /*more adjectives*/].includes(word); 
}

// Example Usage:
const originalSentence = "Beautiful green trees are in the park";
const modifiedSentence = swapAdjectives(originalSentence);
console.log(modifiedSentence); // Output: Green beautiful trees are in the park
