#include <iostream>
#include <limits>

using namespace std;

// Recursive Fibonacci function with error handling
int fibonacci(int a, int b, int n) {
    if (n <= 0) {
        return 0; // Base case: Generate nothing for non-positive counts
    } else if (n == 1) {
        return a;  // First element is provided 'a'
    } else if (n == 2) {
        return b;  // Second element is provided 'b'
    } else {
        return fibonacci(b, a + b, n - 1); // Recursive step
    }
}

int main() {
    int start1, start2, count;

    cout << "Enter the first two integers for the sequence: ";
    while (!(cin >> start1 >> start2)) {  // Input validation: Numeric check
