        cin.ignore(numeric_limits<streamsize>::max(), '\n');
        cerr << "Invalid input. Please enter two integers separated by a space: ";
    }

    cout << "Enter the desired number of sequence elements: ";
    while (!(cin >> count) || count <= 0) {  // Input validation: Numeric and positive count
        cin.clear();
        cin.ignore(numeric_limits<streamsize>::max(), '\n');
        cerr << "Invalid input. Enter a positive integer: ";
    }

    if (start1 < 0 || start2 < 0) {
        cerr << "Error: Both starting integers must be non-negative." << endl;
        return 1; // Indicate an error
    }

    cout << "Fibonacci Sequence (starting with " << start1 << ", " << start2 << "): ";
    for (int i = 1; i <= count; ++i) {
        cout << fibonacci(start1, start2, i) << (i < count ? ", " : "");
        start1 = start2;  // Update for next iteration
        start2 = fibonacci(start1, start2, i); // Calculate and shift values
    }
    cout << endl;

    return 0;
}
