using System;
using System.Net.Http;
using System.Text.Json;
using System.Threading.Tasks;

public class RestServiceWrapper<T> where T : class
{
    private readonly HttpClient _httpClient;
    private readonly string _baseUrl;
    private readonly Action<HttpRequestMessage> _authTokenMiddleware;

    public RestServiceWrapper(string baseUrl, Action<HttpRequestMessage> authTokenMiddleware = null)
    {
        _baseUrl = baseUrl;
        _httpClient = new HttpClient { BaseAddress = new Uri(baseUrl) };
        _authTokenMiddleware = authTokenMiddleware ?? (request => { }); // Default to no auth if not provided
    }

    protected virtual async Task<T> SendRequestInternalAsync(HttpMethod method, string relativeUrl, object content = null, JsonSerializerOptions options = null)
    {
        var request = new HttpRequestMessage(method, relativeUrl)
        {
            Content = content != null ? CreateJsonContent(content, options) : null
        };
        _authTokenMiddleware(request); // Apply authentication middleware here

        HttpResponseMessage response = await _httpClient.SendAsync(request);
        response.EnsureSuccessStatusCode(); // Throw for bad status codes

        string json = await response.Content.ReadAsStringAsync();
        return JsonSerializer.Deserialize<T>(json, options);
    }

    private StringContent CreateJsonContent(object value, JsonSerializerOptions options = null)
    {
        options = options ?? new JsonSerializerOptions { PropertyNamingPolicy = JsonNamingPolicy.CamelCase }; // Consistent naming
        return new StringContent(JsonSerializer.Serialize(value, options), System.Text.Encoding.UTF8, "application/json");
    }

    // Example Usage (Generic Overloads for Clarity)
    public async Task<T> GetAsync(string relativeUrl, JsonSerializerOptions options = null) => 
        await SendRequestInternalAsync(HttpMethod.Get, relativeUrl, null, options);

    public async Task<T> PostAsync<TData>(string relativeUrl, TData data, JsonSerializerOptions options = null) => 
