function determineMostRelevantProtocol(inputData) {
  // **Prioritize based on weighted factors for clarity and helpfulness:**

  const ipv6Match = inputData.sourceIP && inputData.destinationIP &&  /^(([0-9A-Fa-f]{1,4}:){7}[0-9A-Fa-f]{1,4})$/.test(inputData.sourceIP) && /^(([0-9A-Fa-f]{1,4}:){7}[0-9A-Fa-f]{1,4})$/.test(inputData.destinationIP); // Strong IPv6 indication
  const httpMatch = inputData.port === 80 && typeof inputData.payload === 'string'; // Common HTTP port and textual payload

  if (ipv6Match && httpMatch) {  // Highest combined weight: IPv6 AND HTTP characteristics
    return "**Both IPv6 and HTTP are highly relevant**";  // Explicitly stating the combined relevance for clarity
  } else if (ipv6Match) { 
    return "**IPv6 is the most relevant protocol**"; 
  } else if (httpMatch) {
    return "**HTTP is the most relevant protocol**"; 
  } else {
    return "**Insufficient data to definitively determine the primary protocol.**"; //  Handling inconclusive cases
  }
}

