import { Injectable } from '@nestjs/common';
import { CanActivate, ExecutionContext, UnauthorizedException } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { TYPEORM_CONNECTION } from 'typeorm';
import { InjectRepository } from '@nestjs/typeorm';
import { UserRepository } from './user.repository';
import { Role } from './entities/Role.entity';
import { Permission } from './entities/Permission.entity';

const PERMISSIONS = [
  'READ_USERS',
  'CREATE_USERS',
  'UPDATE_USERS',
  'DELETE_USERS',
  'READ_PRODUCTS',
  'CREATE_PRODUCTS',
  'UPDATE_PRODUCTS',
  'DELETE_PRODUCTS',
  // Add more permissions...
];

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(
    private reflector: Reflector,
    @InjectRepository(UserRepository) private userRepository: UserRepository,
    @InjectRepository(Role) private roleRepository: typeof Role,
    @InjectRepository(Permission) private permissionRepository: typeof Permission,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const requiredRoles = this.reflector.get<string[]>('roles', context.getHandler());
    if (!requiredRoles) return true; // Public route

    const request = context.switchToHttp().getRequest();
    const user = request.user;
    if (!user) throw new UnauthorizedException();

    const userRoles = await this.roleRepository.find({ where: { userId: user.id } });
    const permittedPermissions = await this.permissionRepository.find({ relations: ['roles'], where: { roles: { id: userRoles.map(r => r.roleId) } } });
    const hasRequiredPermissions = permittedPermissions.some(perm => requiredRoles.includes(perm.name));

    return hasRequiredPermissions;
  }
}
