/**
 * Searches for a place name in a specified column and retrieves latitude and longitude, storing them in dedicated columns.
 *
 * @param {string} sheetName The name of the Google Sheet containing the data.
 * @param {string} placeNameColumn The header of the column with place names to search (e.g., "Place").
 * @param {string} latColumn The header for the column to store retrieved latitudes.
 * @param {string} lngColumn The header for the column to store retrieved longitudes.
 * @param {string} apiKey Your Google Maps Geocoding API Key (obtain from https://developers.google.com/maps/documentation/geocoding/get-api-key)
 */
function geocodeAndPopulate(sheetName, placeNameColumn, latColumn, lngColumn, apiKey) {
  // 1. Get the Spreadsheet and Worksheet
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);

  // 2. Fetch Data and Prepare for Iteration
  const lastRow = sheet.getLastRow();
  const dataRange = sheet.getRange(2, 1, lastRow - 1, 1).getValues(); // Start from row 2 (assuming header row)
  const placeNames = dataRange.map(row => row[0]); // Extract place names from the specified column

  // 3. Geocoding Loop (using Places API for robust address handling)
  for (let i = 0; i < placeNames.length; i++) {
    const place = placeNames[i];
    const geocoder = new google.maps.Geocoder();
    geocoder.geocode({address: place}, (results, status) => {
      if (status === 'OK' && results.length > 0) {
        const latitude = results[0].geometry.location.lat();
        const longitude = results[0].geometry.location.lng();

        // 4. Update Spreadsheet with Lat/Long
        sheet.getRange(i + 2, sheet.getRange(1, latColumn).getColumn(), 1, 1).setValue(latitude);
        sheet.getRange(i + 2, sheet.getRange(1, lngColumn).getColumn(), 1, 1).setValue(longitude);

