function extractNestedValue(obj, dotNotationKey) {
  const keys = dotNotationKey.split('.'); // Break down the key into individual segments
  let currentLevel = obj;

  // Traverse the object hierarchy using recursion
  for (const key of keys) {
    if (typeof currentLevel === 'object' && currentLevel !== null && key in currentLevel) {
      currentLevel = currentLevel[key]; 
    } else {
      // Key not found at any level, return undefined (or handle as needed for error scenarios)
      return undefined; 
    }
  }
  return currentLevel; // Return the final value found
}

// Example usage:
const options = {
  user: { profile: { name: "Alice", age: 30, location: { city: "New York" } } },
  settings: { theme: "dark" }
};

const desiredKey = "user.profile.city";
const result = extractNestedValue(options, desiredKey);
console.log(result); // Output: "New York"
